package com.acme.harbor.client.rest

import com.acme.harbor.client.generated.clientregistry.RegistryApi
import com.acme.harbor.client.generated.clientregistry.model.RegistryClient
import org.springframework.beans.factory.annotation.Value
import org.springframework.stereotype.Component
import org.springframework.web.client.HttpClientErrorException
import org.springframework.web.client.RestClient

/**
 * Thin wrapper around the client-registry service.
 *
 * `RegistryApi` and `RegistryClient` are generated by openapi-generator from `api/client-registry/client-registry.yaml`
 * into package `com.acme.harbor.client.generated.clientregistry` (target/generated-sources, not committed).
 */
@Component
class ClientRegistryClient(
    restClientBuilder: RestClient.Builder,
    @Value("\${harbor.external.client-registry.base-url}") baseUrl: String,
) {
    private val api = RegistryApi(restClientBuilder.baseUrl(baseUrl).build())

    data class RegistryEntry(val externalRef: String, val name: String, val country: String?, val segment: String?)

    fun search(query: String, limit: Int = 20): List<RegistryEntry> =
        api.searchRegistryClients(q = query, limit = limit).map { it.toEntry() }

    fun findByRef(externalRef: String): RegistryEntry? = try {
        api.getRegistryClient(ref = externalRef).toEntry()
    } catch (e: HttpClientErrorException.NotFound) {
        null
    }

    private fun RegistryClient.toEntry() = RegistryEntry(ref, name, country, segment)
}
